:root{
/*--font-size-title: calc(24px * var(--font-scale));
--font-secondary: "oxygen-regular";*/
--font-size-base: calc(16px * var(--font-scale));
--gray-medium: #2C2C2C;
--gray-base: #5B5B5F;
}

/*-------ajuste css de contraste---------*/
body.theme-contrast .link:is(.btn-contraste *) {
    color: var(--gray-medium) !important;
    background-color: var(--primary)!important;
}
body.theme-contrast .areaBannerInt .bgBanner .areaConteudo .areaTexto a.linkBtn {
    background-color: var(--white-base)!important;
    color: var(--gray-medium) !important;
}
body.theme-contrast .lp_item .menu_superior  {
    background-color: var(--white-base)!important;
}
body.theme-contrast .bg-rgb\(241\,.\32 42\,.\32 45\){
    background-color: #1E1E1E !important;
    color: #fff !important;
}
body.theme-contrast svg .iconArrowBene {
    fill: #FFCC00 ;
} 
body.theme-contrast .sv-titulo h2.font-size-title {
	color: var(--gray-medium);
}
body.theme-contrast .areaBannerInt .bgBanner .areaConteudo .areaTexto p{
color: var(--white-base);
}
/*ajuste para menu superior*/
.lp_item{
  margin-top: 40px;
}
.signed-in .lp_item{
  margin-top: 0px;
}
.areaBannerInt .bgBanner .areaConteudo .areaTexto h1 {
  font-size: 32px;
}
.areaBannerInt .bgBanner .areaConteudo .areaTexto p{
color: var(--gray-base);
}
/*Espaçamento bloco de texto banner interno*/
.areaBannerInt .bgBanner .areaConteudo .areaTexto.ms-auto {
    padding-left: 6%;
}
.sv-titulo h2.font-size-title{
 font-weight:700;
 font-size: var(--font-size-large); 
 font-family: var(--font-primary);
}
.area-cards {
    justify-content: start!important;
}
.btnModal button.link {
 font-weight:bold;
}
.social-section{
margin-top:-48px;
}
/*Ajuste css para antender o tema no link do menu superior*/
.lp_item .menu_superior .botaoBene a{
 font-family: var(--font-primary);
 font-size: var(--font-size-medium);
 text-decoration: underline;
}
/*css custom espçamentos para icone*/
.modelo-2 .area-cardsModelo_2 .card.dropzone .sv-icone-texto .icone-horizontal {
    height: 24px;
    margin-bottom: 0!important;
}
/*css personalizado para mudar o icone das perguntas de duvidas frequentes*/
.sv-faq .question-container button {
    background-image: url("data:image/svg+xml;base64,");
    background-repeat: no-repeat;
    /* position: relative; */
    background-position-x: 100%;
    background-position-y: center;
}

.sv-faq .question-container .plus-icon, .sv-faq .question-container .less-icon {
    display: none;
}
@media (min-width:1600px){
.areaBannerInt .bgBanner .areaConteudo .areaTexto {
    width: 43%!important;
}
}
@media (max-width:768px){
.areaBannerInt .bgBanner  .areaConteudo {
padding-left:0!important;
}
.sv-titulo h2.font-size-title{
 font-size: var(--font-size-title); 
}
.areaBannerInt .bgBanner .areaConteudo{
 padding-left:0;
 padding-right:0;
}
/*ajuste dos faq*/
.sv-faq .question-container button p{
 text-algin:left;
 padding-right: 30px;
}
.social-section{
 padding-left:0!important;
}
.areaBannerInt .bgBanner .areaConteudo .areaTexto.ms-auto {
    padding-left: 0!important; 
}
.sv-icone-texto ul li {
    padding-left: 0;
    padding-right: 0;
}
/*ajuste de espaçamendo do formulario*/
.prevrio-form-wrapper .signup-step-container .container {
    padding:0!important;
}
.prevrio-form-wrapper .signup-step-container {
    padding-bottom: 40px;
}
}
